async () => {
  const projectsResult = await connecta.call('tracker.list_projects', {});
  if (!Array.isArray(projectsResult.projects)) throw new Error('Tracker projects unavailable');
  const projects = await Promise.all(projectsResult.projects.map(async (project) => {
    if (typeof project.id !== 'string') throw new Error('Tracker project id missing');
    const result = await connecta.call('tracker.search_issues', {
      project: project.id,
      status: 'open',
      label: 'bug',
      limit: 1
    });
    if (!Number.isSafeInteger(result.total) || result.total < 0) {
      throw new Error('Tracker bug count unavailable for ' + project.id);
    }
    return { project: project.id, openBugs: result.total };
  }));
  return { projects };
}

async () => {
  const response = await connecta.call('tracker.list_projects', {});
  if (!Array.isArray(response.projects)) throw new Error('Tracker projects unavailable');
  const projects = await Promise.all(response.projects.map(async ({ id }) => {
    if (typeof id !== 'string') throw new Error('Invalid tracker project');
    const result = await connecta.call('tracker.search_issues', {
      project: id, status: 'open', label: 'bug', limit: 1
    });
    if (!Number.isInteger(result.total) || result.total < 0) {
      throw new Error('Invalid open bug count for ' + id);
    }
    return { project: id, openBugs: result.total };
  }));
  return { projects };
}
